// Foundry VTT Macro: Export Compendiums to JSON (V2 Application API)
// Обратная сторона import_from_json_macro.js: выгружает ВСЕ компендиумы dedrel.*
// разом в один JSON-файл (dedrel-export.json), без диалога выбора.
// Файл затем скармливается скрипту scripts/export_foundry_to_markdown.py для
// синхронизации Obsidian-базы. Пути папок компендиума сохраняются в
// flags.dedrel.folder — формат совместим с макросом импорта (раундтрип).
//
// Структура файла:
//   packs       — Item-компендиумы; их и читает питоновский конвертер в Obsidian
//   actor_packs — Actor-компендиумы (2026-07-25), ОТДЕЛЬНЫМ ключом
//
// Почему акторы отдельно: конвертер в Obsidian ходит по `packs` и всё, чего нет
// в TYPE_ROUTES, печатает строкой «Пропущены неподдерживаемые типы». Свалив туда
// стат-блоки, мы бы забивали этот диагностический вывод мусором на каждом прогоне.
// Стат-блоки нужны не для Obsidian, а для проверки данных: предметы на акторе —
// независимые копии, правка компендиума до них не доходит, и любая массовая
// правка ключей молча расходится со стат-блоками (см. NOTES «Слепое пятно
// инструментов: акторы»). В `toObject()` актора входят его embedded `items`
// и `effects` — именно они и нужны для сверки.
(async () => {
    // Служебные паки, которые НЕ выгружаем (напр. склад эффектов — не контент).
    // Пусто по умолчанию: выгружаем всё. Добавь ключ сюда, чтобы исключить.
    const EXCLUDE = new Set([
        // "dedrel.active_effects",
    ]);

    const collect = (documentName) => game.packs
        .filter(p => p.documentName === documentName
            && p.collection.startsWith("dedrel.")
            && !EXCLUDE.has(p.collection))
        .map(p => p.collection)
        .sort();

    const itemPacks = collect("Item");
    const actorPacks = collect("Actor");

    if (!itemPacks.length && !actorPacks.length) {
        return ui.notifications.error("Компендиумы dedrel.* не найдены.");
    }

    // Собирает путь папки документа внутри компендиума: "CON/Rank 6"
    function getFolderPath(doc) {
        const parts = [];
        let folder = doc.folder;
        while (folder) {
            parts.unshift(folder.name);
            folder = folder.folder;
        }
        return parts.join("/");
    }

    const out = {
        exported_at: new Date().toISOString(),
        world: game.world.id,
        system_version: game.system.version,
        packs: {},
        actor_packs: {}
    };

    async function dumpPacks(keys, target) {
        for (const key of keys) {
            const pack = game.packs.get(key);
            if (!pack) {
                ui.notifications.warn(`Компендиум ${key} не найден, пропущен.`);
                continue;
            }
            const docs = await pack.getDocuments();
            target[key] = docs.map(doc => {
                const data = doc.toObject();
                const folderPath = getFolderPath(doc);
                data.flags = data.flags || {};
                data.flags.dedrel = { ...(data.flags.dedrel || {}), folder: folderPath };
                return data;
            });
            console.log(`Dedrel Export | ${key}: ${docs.length} документов`);
        }
    }

    await dumpPacks(itemPacks, out.packs);
    await dumpPacks(actorPacks, out.actor_packs);

    const json = JSON.stringify(out, null, 2);
    const save = foundry.utils.saveDataToFile ?? saveDataToFile;
    save(json, "application/json", "dedrel-export.json");

    const count = (map) => Object.values(map).reduce((n, arr) => n + arr.length, 0);
    const items = count(out.packs);
    const actors = count(out.actor_packs);
    // Предметы на акторах считаем отдельно: это то, что расходится с компендиумом
    const owned = Object.values(out.actor_packs)
        .flat()
        .reduce((n, a) => n + (a.items?.length ?? 0), 0);
    ui.notifications.info(
        `Экспортировано: ${items} документов из ${Object.keys(out.packs).length} Item-компендиумов, `
        + `${actors} акторов (${owned} предметов на них) из ${Object.keys(out.actor_packs).length} Actor-компендиумов.`
    );
})();
